void ScriptSession::clearDialog(std::uint32_t id) {if(!alive(id,NativeKind::Dialog))return;auto d=dialogs_.at(id);auto children=std::move(d->buttons);d->buttons.clear();d->message.clear();++d->revision;for(auto button:children)if(alive(button,NativeKind::Button)){buttons_.erase(button);destroy(runtime_.handle("button",button),NativeKind::Button);}}
std::optional<std::uint32_t> ScriptSession::dialogNetworkFingerprint(std::uint32_t id) const {
    auto button=buttons_.find(id);if(button==buttons_.end())return {};auto dialog=dialogs_.find(button->second->dialog);if(dialog==dialogs_.end())return {};auto& state=*dialog->second;auto selected=std::find(state.buttons.begin(),state.buttons.end(),id);if(selected==state.buttons.end())return {};std::uint32_t value=2166136261u;auto byte=[&](std::uint8_t v){value=(value^v)*16777619u;};auto word=[&](std::uint32_t v){for(unsigned i=0;i<4;++i)byte(std::uint8_t(v>>(8*i)));};word(std::uint32_t(selected-state.buttons.begin()));word(button->second->hotkey);word(button->second->quit);word(button->second->scores);return value;
}
bool ScriptSession::clickDialog(unsigned owner,std::uint32_t id,bool requireVisible,std::uint64_t clickedGeneration,bool finishOnQuit) {
    if(owner>=16 || !alive(id,NativeKind::Button))return false;auto button=buttons_.at(id);auto dialogId=button->dialog;if(!alive(dialogId,NativeKind::Dialog))return false;auto dialog=dialogs_.at(dialogId);if(requireVisible && !(dialog->owners&(1u<<owner)))return false;if(!clickedGeneration || dialog->displayGeneration[owner]<=clickedGeneration)dialog->owners&=~(1u<<owner);std::vector<std::uint32_t> events;for(auto event:eventHandles_)if(alive(event,NativeKind::Event)){auto& e=std::get<ScriptEvent>(objects_[event-handleBase].state);if((e.kind==ScriptEvent::Kind::Dialog && e.target==dialogId) || (e.kind==ScriptEvent::Kind::DialogButton && e.target==id))events.push_back(event);}ScriptContext context;context.triggerPlayer=handleBase+owner;context.clickedDialog=dialogId;context.clickedButton=id;for(auto event:events)fire(event,context);if(finishOnQuit && button->quit && exit_==SessionExit::None)finishGame(button->scores);return true;
}
void ScriptSession::bindScriptDialogNatives() {
    bind("DialogCreate","dialog",{},[this](auto&,auto){if(dialogs_.size()>=256)throw std::runtime_error("Script dialog budget exceeded");auto id=create(NativeKind::Dialog);dialogs_[id.bits]=std::get<std::shared_ptr<ScriptDialog>>(object(id,NativeKind::Dialog).state);return id;});
    bind("DialogDestroy","nothing",{"dialog"},[this](auto& vm,auto a){if(a[0].bits){object(a[0],NativeKind::Dialog);clearDialog(a[0].bits);dialogs_.erase(a[0].bits);destroy(a[0],NativeKind::Dialog);}return vm.nothing();});
    bind("DialogClear","nothing",{"dialog"},[this](auto& vm,auto a){object(a[0],NativeKind::Dialog);clearDialog(a[0].bits);return vm.nothing();});
    bind("DialogSetMessage","nothing",{"dialog","string"},[this](auto& vm,auto a){auto d=std::get<std::shared_ptr<ScriptDialog>>(object(a[0],NativeKind::Dialog).state);d->message=a[1].text?*a[1].text:"";if(d->message.size()>65536)throw std::runtime_error("Script dialog text exceeds budget");++d->revision;return vm.nothing();});
    for(auto [name,quit]:std::initializer_list<std::pair<const char*,bool>>{{"DialogAddButton",false},{"DialogAddQuitButton",true}})bind(name,"button",quit?std::initializer_list<const char*>{"dialog","boolean","string","integer"}:std::initializer_list<const char*>{"dialog","string","integer"},[this,quit](auto&,auto a){auto d=std::get<std::shared_ptr<ScriptDialog>>(object(a[0],NativeKind::Dialog).state);if(d->buttons.size()>=64 || buttons_.size()>=4096)throw std::runtime_error("Script button budget exceeded");auto id=create(NativeKind::Button);auto button=std::get<std::shared_ptr<ScriptButton>>(object(id,NativeKind::Button).state);button->dialog=a[0].bits;button->quit=quit;button->scores=quit && a[1].bits;unsigned at=quit?2:1;button->text=a[at].text?*a[at].text:"";button->hotkey=a[at+1].bits;buttons_[id.bits]=button;d->buttons.push_back(id.bits);++d->revision;return id;});
    bind("DialogDisplay","nothing",{"player","dialog","boolean"},[this](auto& vm,auto a){auto owner=playerId(a[0]);auto d=std::get<std::shared_ptr<ScriptDialog>>(object(a[1],NativeKind::Dialog).state);if(a[2].bits){if(d->displayGeneration[owner]==UINT64_MAX)throw std::runtime_error("Script dialog display generation exhausted");++d->displayGeneration[owner];for(auto& [id,other]:dialogs_)other->owners&=~(1u<<owner);d->owners|=1u<<owner;}else d->owners&=~(1u<<owner);return vm.nothing();});
    for(auto [name,button]:std::initializer_list<std::pair<const char*,bool>>{{"TriggerRegisterDialogEvent",false},{"TriggerRegisterDialogButtonEvent",true}})bind(name,"event",{"trigger",button?"button":"dialog"},[this,button](auto&,auto a){object(a[0],NativeKind::Trigger);object(a[1],button?NativeKind::Button:NativeKind::Dialog);ScriptEvent e;e.owner=a[0].bits;e.target=a[1].bits;e.kind=button?ScriptEvent::Kind::DialogButton:ScriptEvent::Kind::Dialog;e.event=button?90:91;auto id=create(NativeKind::Event);std::get<ScriptEvent>(object(id,NativeKind::Event).state)=std::move(e);return id;});
    bind("GetClickedButton","button",{},[this](auto& vm,auto){return vm.handle("button",contexts_.empty()?0:contexts_.back().clickedButton);});
    bind("GetClickedDialog","dialog",{},[this](auto& vm,auto){return vm.handle("dialog",contexts_.empty()?0:contexts_.back().clickedDialog);});
    bind("CreateDefeatCondition","defeatcondition",{},[this](auto&,auto){if(defeatConditions_.size()>=1024)throw std::runtime_error("Defeat condition budget exceeded");auto id=create(NativeKind::DefeatCondition);defeatConditions_[id.bits]=std::get<std::shared_ptr<ScriptDefeatCondition>>(object(id,NativeKind::DefeatCondition).state);return id;});
    bind("DestroyDefeatCondition","nothing",{"defeatcondition"},[this](auto& vm,auto a){if(a[0].bits){object(a[0],NativeKind::DefeatCondition);defeatConditions_.erase(a[0].bits);destroy(a[0],NativeKind::DefeatCondition);}return vm.nothing();});
    bind("DefeatConditionSetDescription","nothing",{"defeatcondition","string"},[this](auto& vm,auto a){std::get<std::shared_ptr<ScriptDefeatCondition>>(object(a[0],NativeKind::DefeatCondition).state)->description=a[1].text?*a[1].text:"";return vm.nothing();});
}
